        var identity=UUID.randomUUID();var owner=moving(h,ItemStack.EMPTY,ItemStack.EMPTY,DeployerBlockEntity.Mode.USE,be->be.owner=identity);h.assertValueEqual(behaviour().getPlayer(ctx(owner)).getUUID(),identity,"Owner permissions identity");h.succeed();
