        var owner=moving(h,new ItemStack(Items.WATER_BUCKET),ItemStack.EMPTY,DeployerBlockEntity.Mode.USE);visit(h,owner);h.assertBlockPresent(Blocks.WATER,TARGET);h.assertTrue(DeployerMovementBehaviour.getHeldItem(ctx(owner)).is(Items.BUCKET),"Native bucket remainder");h.assertBlockPresent(Blocks.AIR,TARGET.south());h.succeed();
