    @GameTest public void fireConveniencePlacementHonorsProtectionOfTheActualWorkCell(GameTestHelper h)throws Exception{
        var owner=moving(h,new ItemStack(Items.FLINT_AND_STEEL),ItemStack.EMPTY,DeployerBlockEntity.Mode.USE);h.setBlock(TARGET.below(),Blocks.STONE);var target=h.absolutePos(TARGET);DeployerTestFixtures.DENY_USE.add(target);try{visit(h,owner);h.assertBlockPresent(Blocks.AIR,TARGET);h.assertValueEqual(DeployerMovementBehaviour.getHeldItem(ctx(owner)).getDamageValue(),0,"Denied ignition keeps tool");}finally{DeployerTestFixtures.DENY_USE.remove(target);}h.succeed();
    }
    private static void machine(GameTestHelper h){h.setBlock(P,state());var deployer=h.getBlockEntity(P,DeployerBlockEntity.class);deployer.setHeldItem(new ItemStack(Items.WOODEN_PICKAXE));deployer.setFilter(new ItemStack(Items.WOODEN_PICKAXE));deployer.changeMode();h.setBlock(P.east(),Blocks.BARREL);h.setBlock(TARGET,Blocks.STONE);h.getLevel().addFreshEntity(new SuperGlueEntity(h.getLevel(),SuperGlueEntity.span(h.absolutePos(P),h.absolutePos(P.east()))));h.setBlock(B,AllBlocks.MECHANICAL_BEARING.defaultBlockState().setValue(BearingBlock.FACING,Direction.UP));h.setBlock(B.below(),AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(com.simibubi.create.content.kinetics.motor.CreativeMotorBlock.FACING,Direction.UP));}
    @GameTest(maxTicks=210) public void actualKineticBearingDeployerStallsPunchesCollectsAndResumes(GameTestHelper h){
        machine(h);h.runAfterDelay(12,()->{var owner=h.getBlockEntity(B,MechanicalBearingBlockEntity.class).getMovedContraption();h.assertTrue(owner!=null&&owner.isStalled(),"Actual punch holds bearing");h.assertTrue(ctx(owner).data.getFloatOr("BreakingProgress",0)>0,"Real native player progress");});h.runAfterDelay(180,()->{var owner=h.getBlockEntity(B,MechanicalBearingBlockEntity.class).getMovedContraption();h.assertBlockPresent(Blocks.AIR,TARGET);h.assertValueEqual(count(owner,Items.COBBLESTONE),1L,"Collected one actual block");h.assertFalse(owner.isStalled(),"Bearing resumed");h.succeed();});
    }
